/* eslint-disable max-len, id-length */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var dlaqr1 = require( './../lib/dlaqr1.js' );


// FIXTURES //

var N_EQ_THREE_NONZERO_ROW_MAJOR = require( './fixtures/n_eq_three_nonzero_row_major.json' );
var N_EQ_THREE_NONZERO_COL_MAJOR = require( './fixtures/n_eq_three_nonzero_col_major.json' );
var N_EQ_THREE_ZERO_ROW_MAJOR = require( './fixtures/n_eq_three_zero_row_major.json' );
var N_EQ_THREE_ZERO_COL_MAJOR = require( './fixtures/n_eq_three_zero_col_major.json' );
var N_EQ_TWO_NONZERO_ROW_MAJOR = require( './fixtures/n_eq_two_nonzero_row_major.json' );
var N_EQ_TWO_NONZERO_COL_MAJOR = require( './fixtures/n_eq_two_nonzero_col_major.json' );
var N_EQ_TWO_ZERO_ROW_MAJOR = require( './fixtures/n_eq_two_zero_row_major.json' );
var N_EQ_TWO_ZERO_COL_MAJOR = require( './fixtures/n_eq_two_zero_col_major.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlaqr1, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 9', function test( t ) {
	t.strictEqual( dlaqr1.length, 9, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var data;
	var H;
	var V;
	var i;

	data = N_EQ_THREE_NONZERO_COL_MAJOR;
	H = new Float64Array( data.H );
	V = new Float64Array( data.V );

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaqr1( value, data.N, H, data.LDH, data.sr1, data.si1, data.sr2, data.si2, V );
		};
	}
});

tape( 'the function throws an error if provided a fourth argument which is not a valid `LDH` value (row-major)', function test( t ) {
	var values;
	var data;
	var H;
	var V;
	var i;

	data = N_EQ_THREE_NONZERO_ROW_MAJOR;
	H = new Float64Array( data.H );
	V = new Float64Array( data.V );

	values = [
		0,
		1,
		2
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dlaqr1( data.order, data.N, H, value, data.sr1, data.si1, data.sr2, data.si2, V );
		};
	}
});

