tape( 'the function returns expected value for N = 3 (zero vector output) (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var V;
	var H;

	data = N_EQ_THREE_ZERO_ROW_MAJOR;
	V = new Float64Array( data.V );
	H = new Float64Array( data.H );
	expected = new Float64Array( data.V_out );

	out = dlaqr1( data.order, data.N, H, data.LDH, data.sr1, data.si1, data.sr2, data.si2, V );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

